(() => {
const canvas=document.getElementById('world'),ctx=canvas.getContext('2d');
const colors=['#c98468','#7b9b76','#c79b61','#758aa2','#a77f9c','#759b9b','#b67d69','#9b9d65'];
const initial={day:1,hour:7,food:124,water:86,wood:42,stone:28,paused:false,speed:1,weather:'Light rain',temp:18,leader:'Mairi',season:'Early wet season',field:{health:78,water:67,stage:'Growing',yield:42},people:[
{name:'Mairi',age:34,role:'Community leader',trait:'Patient · Diplomatic',hunger:76,energy:82,mood:88,skill:'Leadership',family:'Tevai family'},
{name:'Rangi',age:38,role:'Taro farmer',trait:'Steady · Industrious',hunger:68,energy:72,mood:75,skill:'Farming',family:'Tevai family'},
{name:'Hina',age:31,role:'Fisher',trait:'Curious · Sociable',hunger:72,energy:66,mood:82,skill:'Fishing',family:'Ari’i family'},
{name:'Tane',age:56,role:'Stoneworker',trait:'Thoughtful · Skilled',hunger:63,energy:55,mood:79,skill:'Crafting',family:'Tevai family'},
{name:'Ari',age:12,role:'Young learner',trait:'Bright · Restless',hunger:81,energy:91,mood:93,skill:'Gathering',family:'Ari’i family'},
{name:'Pua',age:8,role:'Child',trait:'Playful · Observant',hunger:74,energy:90,mood:95,skill:'Learning',family:'Ari’i family'},
{name:'Moana',age:42,role:'Gardener',trait:'Generous · Resilient',hunger:70,energy:68,mood:81,skill:'Farming',family:'Moana family'},
{name:'Tiare',age:27,role:'Weaver',trait:'Patient · Creative',hunger:66,energy:79,mood:85,skill:'Crafting',family:'Moana family'},
{name:'Pita',age:63,role:'Elder · storyteller',trait:'Wise · Cautious',hunger:59,energy:43,mood:84,skill:'Knowledge',family:'Tevai family'},
{name:'Mako',age:24,role:'Fisher',trait:'Courageous · Bold',hunger:79,energy:71,mood:77,skill:'Fishing',family:'Ari’i family'},
{name:'Vaea',age:19,role:'Gatherer',trait:'Quiet · Curious',hunger:72,energy:80,mood:80,skill:'Gathering',family:'Moana family'},
{name:'Roa',age:4,role:'Child',trait:'Cheerful · Lively',hunger:87,energy:94,mood:97,skill:'Learning',family:'Moana family'}],journal:[{day:1,text:'The first rain of the season settles over Ha’urei Bay. The stream is running clear, and the community begins its morning together.'}],buildings:[],activeTab:'community',action:'rest',leaderPos:{x:.5,y:.59},zoom:1,seed:1234};
let S;try{S=JSON.parse(localStorage.getItem('rapa-save'))||initial}catch{S=initial} if(!S.people||!S.journal)S=initial;
let last=performance.now(),acc=0,toastTimer;
function save(){localStorage.setItem('rapa-save',JSON.stringify(S));toast('Your island is safely remembered.');}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function log(text){S.journal.unshift({day:S.day,text});S.journal=S.journal.slice(0,30)}
function hourText(){const h=Math.floor(S.hour)%24;return `${String(h%12||12).padStart(2,'0')}:${h<12?'AM':'PM'}`}
function timeStep(){S.hour+=.25*S.speed;if(S.hour>=24){S.hour-=24;S.day++;daily();} if(Math.random()<.006){const w=['Passing showers','Mountain mist','Overcast','Strong wind','Light rain'];S.weather=w[Math.floor(Math.random()*w.length)];S.temp=17+Math.floor(Math.random()*5)} renderPanel();updateTop();}
function daily(){S.food=Math.max(0,S.food-S.people.length*1.35);S.water=Math.max(0,S.water-S.people.length*.72);S.field.water=Math.min(100,S.field.water+(S.weather.includes('rain')?12:4));S.field.health=Math.max(20,Math.min(100,S.field.health+(S.field.water>35?2:-4)));S.people.forEach(p=>{p.hunger=Math.max(15,p.hunger-8+Math.random()*5);p.energy=Math.min(100,p.energy+10);p.mood=Math.max(32,Math.min(100,p.mood+(S.food>20?1:-5)+(S.water>10?1:-3)));});if(S.food<20)log('Food stores are running low. Households are sharing what remains; a harvest is needed soon.');else if(S.day%3===0)log(`Day ${S.day}: rain softens the valley soil. The taro terraces are ${S.field.health>65?'looking healthy':'in need of care'}.`);if(S.day%12===0&&S.people.length<22){let names=['Miri','Hau','Tama','Rima'];let n=names[Math.floor(Math.random()*names.length)];S.people.push({name:n,age:Math.random()<.5?1:26,role:'Community member',trait:'Warm · Adaptable',hunger:80,energy:85,mood:90,skill:'Gathering',family:'New household'});log(`${n} joins the community through family ties. The settlement welcomes a new generation.`)} updateTop();renderPanel();}
function act(type){switch(type){case'fish': if(S.hour<6||S.hour>19){toast('The shore is too dark for a safe fishing trip.');return} S.food+=13;S.people.find(p=>p.skill==='Fishing').energy-=12;S.leaderPos={x:.76,y:.6};log('A short fishing trip brings reef fish and shellfish back to the cooking fire.');toast('A good catch: +13 food.');break;case'harvest':if(S.field.stage==='Growing'&&S.field.health<35){toast('The taro needs more time to recover.');return}let y=Math.round(S.field.yield*(S.field.health/100));S.food+=y;S.field.health=Math.max(38,S.field.health-18);S.field.water=Math.max(25,S.field.water-15);S.field.stage='Growing';log(`The community harvests ${y} portions of taro from the pondfields.`);toast(`Harvest gathered: +${y} food.`);break;case'gather':S.food+=5;S.water+=4;S.wood+=3;log('Gatherers return with edible greens, clean stream water, and fallen wood.');toast('Gathered food, water, and wood.');break;case'plant':if(S.food<8){toast('Keep some food for the households before planting.');return}S.food-=8;S.field.health=Math.min(100,S.field.health+12);S.field.water=Math.min(100,S.field.water+8);S.field.stage='New shoots';S.field.yield+=5;log('New taro huli are planted in the wet field. The next harvest will take time.');toast('Taro planted — the field is growing.');break;case'build':openBuild();return;case'rest':{let p=S.people[0];p.energy=Math.min(100,p.energy+20);p.mood=Math.min(100,p.mood+2);log('You take a quiet moment with family, listening to rain move across the bay.');toast('A moment of rest. Energy restored.');break}}updateTop();renderPanel();}
function updateTop(){document.getElementById('foodTop').textContent=Math.floor(S.food);document.getElementById('waterTop').textContent=Math.floor(S.water);document.getElementById('peopleTop').textContent=S.people.length;document.getElementById('dateLabel').textContent=`Day ${S.day} · ${S.season}`;document.getElementById('weatherLabel').textContent=`${S.weather} · ${S.temp}°C`;document.getElementById('leaderName').textContent=S.leader;document.getElementById('leaderAvatar').textContent=S.leader[0];}
const $=s=>document.querySelector(s);
function renderPanel(){let panel=$('#panel');if(S.activeTab==='community'){panel.innerHTML=`<div class="greeting">A new day in Ha’urei</div><div class="subcopy">${hourText()} · The bay is waking beneath a veil of cloud. Your people are beginning their day.</div><div class="status-card"><div class="status-head"><span>Community wellbeing</span><span class="pill">${S.food<20?'Needs attention':'Steady'}</span></div><div class="meter"><span style="width:${Math.max(14,Math.min(100,Math.round((S.food/1.2+S.water)/2)))}%"></span></div><p>${S.food<20?'Stores are low. Organize a fishing trip or harvest to support the households.':'The shared stores are holding. A balanced day of fieldwork and gathering will keep them healthy.'}</p><div class="needs"><div class="need ${S.food<25?'warn':''}"><label>FOOD STORES</label><b>${Math.floor(S.food)} portions</b></div><div class="need ${S.water<18?'warn':''}"><label>FRESH WATER</label><b>${Math.floor(S.water)} vessels</b></div><div class="need"><label>HOUSEHOLDS</label><b>${new Set(S.people.map(p=>p.family)).size} families</b></div></div></div><div class="section-title">YOUR COMMUNITY <span style="float:right;color:#9aa398;font-weight:500;letter-spacing:0">${S.people.length} people</span></div><div class="people-list">${S.people.slice(0,7).map((p,i)=>`<div class="person" data-person="${i}"><div class="person-face" style="background:${colors[i%colors.length]}">${p.name[0]}</div><div class="person-main"><strong>${p.name}${p.name===S.leader?' · you':''}</strong><small>${p.role} · ${p.age} years</small></div><div class="person-meta"><b>${p.mood>75?'Content':p.mood>50?'Settled':'Worried'}</b>${p.family.split(' ')[0]}</div></div>`).join('')}</div>${S.people.length>7?`<button class="small-btn" style="margin-top:8px" id="morePeople">View all ${S.people.length} residents</button>`:''}`;
}else if(S.activeTab==='land'){panel.innerHTML=`<div class="greeting">Land & livelihood</div><div class="subcopy">A narrow valley between steep ridges; every field and stream matters.</div><div class="section-title">TARO PONDFIELDS</div><div class="field-card"><header><span>Ha’urei terraces</span><span style="color:#76916c">${S.field.stage}</span></header><p>Water channels link these small fields to the stream. Rain helps replenish them; careful tending protects the harvest.</p><div class="needs"><div class="need"><label>FIELD HEALTH</label><b>${Math.round(S.field.health)}%</b></div><div class="need"><label>WATER LEVEL</label><b>${Math.round(S.field.water)}%</b></div><div class="need"><label>EST. HARVEST</label><b>${Math.round(S.field.yield*S.field.health/100)} portions</b></div></div><div class="field-actions" style="margin-top:11px"><button class="small-btn" data-action="plant">Plant taro · 8 food</button><button class="small-btn" data-action="harvest">Harvest field</button></div></div><div class="section-title">COMMUNITY MATERIALS</div><div class="needs"><div class="need"><label>WOOD</label><b>${Math.floor(S.wood)} bundles</b></div><div class="need"><label>STONE</label><b>${Math.floor(S.stone)} pieces</b></div><div class="need"><label>RAINFALL</label><b>${S.weather}</b></div></div><div class="section-title">AROUND THE BAY</div><div class="status-card"><div class="status-head"><span>Stream & forest</span><span class="pill">Healthy</span></div><p>Fresh water descends from the misty heights. The community gathers fallen wood and plants without clearing the valley forest.</p><button class="small-btn" data-action="gather">Organize gathering</button></div><div class="status-card"><div class="status-head"><span>Coastal fishing ground</span><span class="pill">Open</span></div><p>Shallow coves support shellfish and reef fish. Wind and swell determine when it is safe to go out.</p><button class="small-btn" data-action="fish">Go fishing</button></div>`;
}else{panel.innerHTML=`<div class="greeting">Community journal</div><div class="subcopy">A living record of the people and seasons of Ha’urei Bay.</div><div class="section-title">RECENT MEMORIES</div>${S.journal.map(e=>`<div class="journal-item"><small>DAY ${e.day} · ${e.day===S.day?hourText():'RECORDED'}</small><p>${e.text}</p></div>`).join('')}`;}
}
function openModal(html){$('#modalContent').innerHTML=html;$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden')}
function openBuild(){openModal(`<div class="eyebrow" style="color:#859681">SETTLEMENT PLANNING</div><h2>Build together</h2><p>Projects use shared materials and take time. Choose a useful addition to the settlement.</p><div class="choice-row"><button data-build="dwelling">Family dwelling<br><small>12 wood · 6 stone</small></button><button data-build="canoe shelter">Canoe shelter<br><small>10 wood · 3 stone</small></button><button data-build="terrace wall">Terrace wall<br><small>4 wood · 14 stone</small></button></div><p id="buildHint" style="min-height:18px"></p><button class="primary-action" id="confirmBuild">Start project</button>`);let choice='dwelling';document.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>{choice=b.dataset.build;document.querySelectorAll('[data-build]').forEach(x=>x.classList.toggle('selected',x===b));$('#buildHint').textContent=`${choice[0].toUpperCase()+choice.slice(1)} chosen. A few hands will work on it over the coming days.`});$('#confirmBuild').onclick=()=>{let costs=choice==='terrace wall'?[4,14]:choice==='canoe shelter'?[10,3]:[12,6];if(S.wood<costs[0]||S.stone<costs[1]){toast('The community store does not have enough materials yet.');return}S.wood-=costs[0];S.stone-=costs[1];S.buildings.push({type:choice,progress:0,x:.43+Math.random()*.15,y:.55+Math.random()*.09});log(`A ${choice} project begins near the settlement. Neighbours share the work.`);closeModal();toast(`${choice} project started.`);renderPanel()};}
function personModal(i){let p=S.people[i];openModal(`<div class="eyebrow" style="color:#859681">A PERSON OF HA’UREI</div><h2>${p.name}</h2><p>${p.age} years old · ${p.role}<br>${p.family} · ${p.trait}</p><div class="section-title">TODAY</div><div class="needs"><div class="need"><label>MOOD</label><b>${Math.round(p.mood)}%</b></div><div class="need"><label>ENERGY</label><b>${Math.round(p.energy)}%</b></div><div class="need"><label>HUNGER</label><b>${Math.round(p.hunger)}%</b></div></div><div class="status-card"><div class="status-head"><span>Growing skill</span><span class="pill">${p.skill}</span></div><p>${p.name} contributes to the life of the settlement through daily work, family ties, and shared responsibilities.</p></div><button class="primary-action" id="closePerson">Spend time together</button>`);$('#closePerson').onclick=()=>{p.mood=Math.min(100,p.mood+7);p.energy=Math.max(0,p.energy-3);log(`You spend a little time with ${p.name}; a conversation makes the day feel lighter.`);closeModal();renderPanel();toast(`${p.name} appreciates the visit.`)}}

function draw(){const dpr=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;if(canvas.width!==Math.round(r.width*dpr)||canvas.height!==Math.round(r.height*dpr)){canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);const w=r.width,h=r.height,t=performance.now()/1000;let sx=w/900,sy=h/600;ctx.clearRect(0,0,w,h);ctx.save();ctx.scale(sx,sy);ctx.fillStyle='#47767b';ctx.fillRect(0,0,900,600);
// Ocean depth and bay
let sea=ctx.createLinearGradient(0,0,800,600);sea.addColorStop(0,'#527d82');sea.addColorStop(.55,'#39747a');sea.addColorStop(1,'#285d66');ctx.fillStyle=sea;ctx.fillRect(0,0,900,600);
for(let i=0;i<20;i++){let x=(i*67+t*4)%1000-40,y=(i*97)%540+20;ctx.strokeStyle=`rgba(202,225,209,${.06+(i%3)*.025})`;ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(x,y,18+(i%4)*7,2,Math.sin(i)*.08,0,Math.PI*2);ctx.stroke()}
// Island body
ctx.beginPath();ctx.moveTo(132,350);ctx.bezierCurveTo(139,300,182,273,213,251);ctx.bezierCurveTo(236,215,257,174,312,166);ctx.bezierCurveTo(346,135,388,152,423,122);ctx.bezierCurveTo(458,93,502,119,535,144);ctx.bezierCurveTo(585,144,601,186,637,190);ctx.bezierCurveTo(685,204,710,246,756,260);ctx.bezierCurveTo(796,283,795,337,775,369);ctx.bezierCurveTo(748,407,706,408,685,436);ctx.bezierCurveTo(646,473,606,473,574,455);ctx.bezierCurveTo(536,480,489,466,459,447);ctx.bezierCurveTo(417,465,374,445,349,423);ctx.bezierCurveTo(308,444,270,420,244,400);ctx.bezierCurveTo(203,405,171,386,132,350);ctx.closePath();ctx.fillStyle='#344f46';ctx.fill();ctx.strokeStyle='#92aa87';ctx.lineWidth=2;ctx.stroke();
// land lush layered valleys
ctx.save();ctx.beginPath();ctx.moveTo(132,350);ctx.bezierCurveTo(139,300,182,273,213,251);ctx.bezierCurveTo(236,215,257,174,312,166);ctx.bezierCurveTo(346,135,388,152,423,122);ctx.bezierCurveTo(458,93,502,119,535,144);ctx.bezierCurveTo(585,144,601,186,637,190);ctx.bezierCurveTo(685,204,710,246,756,260);ctx.bezierCurveTo(796,283,795,337,775,369);ctx.bezierCurveTo(748,407,706,408,685,436);ctx.bezierCurveTo(646,473,606,473,574,455);ctx.bezierCurveTo(536,480,489,466,459,447);ctx.bezierCurveTo(417,465,374,445,349,423);ctx.bezierCurveTo(308,444,270,420,244,400);ctx.bezierCurveTo(203,405,171,386,132,350);ctx.closePath();ctx.clip();let land=ctx.createLinearGradient(200,150,650,470);land.addColorStop(0,'#779474');land.addColorStop(.45,'#587a5d');land.addColorStop(1,'#45634e');ctx.fillStyle=land;ctx.fillRect(120,100,700,400);
// ridges / mountain folds
for(let i=0;i<12;i++){let x=235+i*43,y=250+Math.sin(i*1.35)*83;ctx.beginPath();ctx.moveTo(x-100,y+140);ctx.quadraticCurveTo(x,y-100-(i%3)*22,x+155,y+130);ctx.quadraticCurveTo(x+65,y+95,x-100,y+140);ctx.fillStyle=i%2?'rgba(152,176,132,.12)':'rgba(34,66,53,.17)';ctx.fill();ctx.strokeStyle='rgba(204,214,178,.10)';ctx.lineWidth=2;ctx.stroke()}
// mist on peaks
for(let i=0;i<7;i++){let x=280+i*55,y=193+Math.sin(i)*27;ctx.fillStyle=`rgba(213,225,209,${.16+Math.sin(t+i)*.04})`;ctx.beginPath();ctx.ellipse(x,y,38,10,Math.sin(i)*.1,0,Math.PI*2);ctx.fill()}
// forest texture tree clusters
let rand=(n)=>{let x=Math.sin(n*127.1+S.seed)*43758.5453;return x-Math.floor(x)};for(let i=0;i<135;i++){let x=178+rand(i)*570,y=195+rand(i+91)*250;if((x>420&&x<650&&y>300&&y<430)||(x>300&&x<450&&y>220&&y<310))continue;let rr=4+rand(i+32)*6;ctx.fillStyle=['#365d46','#4d704f','#66845b','#426b50'][i%4];ctx.beginPath();ctx.ellipse(x,y,rr,rr*.7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(198,199,147,.14)';ctx.beginPath();ctx.arc(x-2,y-2,rr*.32,0,Math.PI*2);ctx.fill()}
// central valley clearing
ctx.fillStyle='rgba(177,180,126,.23)';ctx.beginPath();ctx.moveTo(346,319);ctx.quadraticCurveTo(395,284,469,309);ctx.quadraticCurveTo(515,326,564,364);ctx.quadraticCurveTo(508,416,423,409);ctx.quadraticCurveTo(366,390,346,319);ctx.fill();
// Stream from mountain through fields
ctx.beginPath();ctx.moveTo(511,191);ctx.bezierCurveTo(475,231,492,257,460,282);ctx.bezierCurveTo(433,310,483,337,450,363);ctx.bezierCurveTo(422,388,451,407,428,430);ctx.strokeStyle='#72aeb0';ctx.lineWidth=8;ctx.lineCap='round';ctx.stroke();ctx.beginPath();ctx.moveTo(511,191);ctx.bezierCurveTo(475,231,492,257,460,282);ctx.bezierCurveTo(433,310,483,337,450,363);ctx.bezierCurveTo(422,388,451,407,428,430);ctx.strokeStyle='#a1ccbf';ctx.lineWidth=2;ctx.stroke();
// Pondfields terraces
for(let i=0;i<5;i++){let x=401+i*19,y=342+i*8;ctx.fillStyle=['#799a62','#89a96b','#73965f'][i%3];ctx.beginPath();ctx.ellipse(x,y,25,9,-.35,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#b9b486';ctx.lineWidth=2;ctx.stroke();for(let j=0;j<4;j++){ctx.strokeStyle='rgba(218,220,168,.36)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x-13+j*7,y-3);ctx.lineTo(x-13+j*7,y+3);ctx.stroke()}}
// small wooded bay inset shore
ctx.restore();
// sheltered bay lagoon
ctx.fillStyle='#4e8888';ctx.beginPath();ctx.moveTo(733,316);ctx.quadraticCurveTo(679,293,634,311);ctx.quadraticCurveTo(603,327,586,354);ctx.quadraticCurveTo(632,378,689,374);ctx.quadraticCurveTo(727,361,733,316);ctx.fill();ctx.strokeStyle='#c2c6a2';ctx.lineWidth=3;ctx.stroke();
// footpaths
ctx.beginPath();ctx.moveTo(451,378);ctx.quadraticCurveTo(493,359,529,345);ctx.quadraticCurveTo(565,335,611,349);ctx.strokeStyle='#c9b894';ctx.lineWidth=4;ctx.setLineDash([2,4]);ctx.stroke();ctx.setLineDash([]);
// settlement huts
function hut(x,y,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle='#283e35';ctx.beginPath();ctx.ellipse(0,8,17,6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#bd9c6e';ctx.fillRect(-10,-5,20,13);ctx.fillStyle='#786247';ctx.beginPath();ctx.moveTo(-14,-4);ctx.lineTo(0,-16);ctx.lineTo(14,-4);ctx.closePath();ctx.fill();ctx.strokeStyle='#e3c58f';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-11,-3);ctx.lineTo(0,-13);ctx.lineTo(11,-3);ctx.stroke();ctx.fillStyle='#473e30';ctx.fillRect(-2,1,5,7);ctx.restore()}
[[477,375],[510,361],[531,380],[487,397],[552,365],[519,403]].forEach((p,i)=>hut(p[0],p[1],i===0?1.12:.85));
// people moving around settlement
S.people.slice(0,8).forEach((p,i)=>{let phase=t*.25+i*1.7,x=493+Math.cos(phase)*25+i%3*3,y=387+Math.sin(phase)*13;ctx.fillStyle=colors[i%colors.length];ctx.beginPath();ctx.arc(x,y-3,3.8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#3d453b';ctx.fillRect(x-2,y,4,6)});
// leader marker
let lx=S.leaderPos.x*900,ly=S.leaderPos.y*600;ctx.beginPath();ctx.arc(lx,ly-11,13+Math.sin(t*2)*1.5,0,Math.PI*2);ctx.strokeStyle='rgba(255,244,203,.8)';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#e9bf7c';ctx.beginPath();ctx.arc(lx,ly-11,5,0,Math.PI*2);ctx.fill();
// building progress markers
S.buildings.forEach(b=>{let x=b.x*900,y=b.y*600;ctx.fillStyle='#f6e5bd';ctx.font='10px sans-serif';ctx.fillText('✦ '+b.type,x,y);});
// rain and clouds
for(let i=0;i<8;i++){let x=((i*143+t*7)%(1000))-30,y=52+(i%4)*24;ctx.fillStyle=`rgba(221,231,222,${.13+Math.sin(t+i)*.025})`;ctx.beginPath();ctx.ellipse(x,y,70,17,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(x-22,y-6,32,14,0,0,Math.PI*2);ctx.ellipse(x+20,y-5,39,16,0,0,Math.PI*2);ctx.fill()}if(S.weather.toLowerCase().includes('rain'))for(let i=0;i<45;i++){let x=(i*97+t*55)%900,y=(i*71+t*120)%600;ctx.strokeStyle='rgba(210,229,226,.27)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y+8);ctx.stroke()}
// offshore bird silhouettes
